import numpy as np, mujoco
from scipy.spatial.transform import Rotation as R
from PIL import Image
class Controller:
 def __init__(self,s):
  self.s=s; self.m=s.model; self.d=s.data
  self.ikd=mujoco.MjData(self.m)
  self.jids=[self.m.joint('robot0_joint'+str(i)).id for i in range(1,8)]
  self.qa=self.m.jnt_qposadr[self.jids]; self.va=self.m.jnt_dofadr[self.jids]
  self.limits=self.m.jnt_range[self.jids]
  self.sid=s.env.robots[0].eef_site_id['right']
  self.down=np.array([[0,1,0],[1,0,0],[0,0,-1.]])
  self.grip=-1
 def pos(self): return self.d.site_xpos[self.sid].copy()
 def rot(self): return self.d.site_xmat[self.sid].reshape(3,3).copy()
 def obj(self,name): return self.d.xpos[self.m.body(name+'_main').id].copy()
 def ik(self,pos,rot,seed=None):
  d=self.ikd; d.qpos[:]=self.d.qpos; q=self.d.qpos[self.qa].copy() if seed is None else seed.copy()
  jp=np.zeros((3,self.m.nv)); jr=jp.copy()
  for _ in range(120):
   d.qpos[self.qa]=q; mujoco.mj_kinematics(self.m,d); mujoco.mj_comPos(self.m,d)
   e=np.r_[pos-d.site_xpos[self.sid],R.from_matrix(rot@d.site_xmat[self.sid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5: break
   mujoco.mj_jacSite(self.m,d,jp,jr,self.sid); J=np.vstack([jp[:,self.va],jr[:,self.va]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*0.0001,e)
   q=np.clip(q+np.clip(dq,-.15,.15),self.limits[:,0]+.001,self.limits[:,1]-.001)
  return q,np.linalg.norm(e)
 def step(self,q=None,grip=None,base=None,torso=0):
  a=self.s.hold_targets(); a[:7]=self.d.qpos[self.qa] if q is None else q
  if grip is not None:self.grip=grip
  a[7]=self.grip; a[8:11]=[0,0,0] if base is None else base; a[11]=torso; a[12]=-1
  return self.s.step(a)
 def hold(self,n=15,grip=None):
  q=self.s.targets[:7].copy()
  for _ in range(n):self.step(q,grip)
 def move(self,pos,rot=None,n=50,grip=None):
  pos=np.array(pos); rot=self.down if rot is None else rot
  p0=self.pos(); r0=R.from_matrix(self.rot()); dr=R.from_matrix(rot@r0.as_matrix().T).as_rotvec(); q=self.d.qpos[self.qa].copy()
  for i in range(n):
   t=(i+1)/n; t=t*t*(3-2*t)
   rt=R.from_rotvec(dr*t).as_matrix()@r0.as_matrix()
   q,err=self.ik(p0+(pos-p0)*t,rt,seed=q)
   self.step(q,grip)
  self.hold(8)
  print('move',len(self.s.actions),'err',round(err,4),'actual',self.pos().round(4), 'obj',self.obj('obj1').round(3),self.obj('obj2').round(3),flush=True)
 def joint(self,q,n=60):
  q0=self.d.qpos[self.qa].copy()
  for i in range(n):
   t=(i+1)/n; t=t*t*(3-2*t); self.step(q0+(q-q0)*t)
  self.hold(10)
 def base(self,delta,n=100):
  q=self.s.targets[:7].copy()
  for _ in range(n):self.step(q,base=delta)
  self.hold(10)
  print('base',self.d.xpos[self.m.body('mobilebase0_base').id],flush=True)
 def snap(self,name):Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')
